BEGIN;
CREATE TABLE app.supplier_match_proposal(id uuid NOT NULL,tenant_id uuid NOT NULL,job_id uuid NOT NULL,digest char(64) NOT NULL,state varchar(20) NOT NULL CHECK(state IN('matched','ambiguous')),ambiguity_reason varchar(40),order_revision_id uuid NOT NULL,receipt_version_ids uuid[] NOT NULL CHECK(cardinality(receipt_version_ids)>0),bill_revision_id uuid NOT NULL,actor_ref text NOT NULL,subject_ref uuid NOT NULL,payload_hash char(64) NOT NULL,audit_event_id uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT transaction_timestamp(),PRIMARY KEY(tenant_id,id),UNIQUE(tenant_id,job_id,id),UNIQUE(tenant_id,job_id,digest),FOREIGN KEY(tenant_id,job_id,order_revision_id)REFERENCES app.purchase_order_revision(tenant_id,job_id,id),FOREIGN KEY(tenant_id,job_id,bill_revision_id)REFERENCES app.supplier_fact_revision(tenant_id,job_id,id),FOREIGN KEY(tenant_id,audit_event_id)REFERENCES app.audit_event(tenant_id,id) DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE app.supplier_match_revision(id uuid NOT NULL,tenant_id uuid NOT NULL,job_id uuid NOT NULL,proposal_id uuid NOT NULL,command_id uuid NOT NULL,revision integer NOT NULL CHECK(revision>0),order_revision_id uuid NOT NULL,receipt_version_ids uuid[] NOT NULL CHECK(cardinality(receipt_version_ids)>0),bill_revision_id uuid NOT NULL,actor_ref text NOT NULL,subject_ref uuid NOT NULL,payload_hash char(64) NOT NULL,audit_event_id uuid NOT NULL,invalidates_unresolved_findings boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT transaction_timestamp(),PRIMARY KEY(tenant_id,id),UNIQUE(tenant_id,command_id),UNIQUE(tenant_id,job_id,id),UNIQUE(tenant_id,job_id,proposal_id,revision),FOREIGN KEY(tenant_id,job_id,proposal_id)REFERENCES app.supplier_match_proposal(tenant_id,job_id,id),FOREIGN KEY(tenant_id,job_id,order_revision_id)REFERENCES app.purchase_order_revision(tenant_id,job_id,id),FOREIGN KEY(tenant_id,job_id,bill_revision_id)REFERENCES app.supplier_fact_revision(tenant_id,job_id,id),FOREIGN KEY(tenant_id,audit_event_id)REFERENCES app.audit_event(tenant_id,id) DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE app.supplier_match_allocation(id uuid NOT NULL,tenant_id uuid NOT NULL,job_id uuid NOT NULL,match_revision_id uuid NOT NULL,receipt_version_id uuid NOT NULL,quantity_decimal numeric(20,6) NOT NULL CHECK(quantity_decimal>0),unit varchar(30) NOT NULL,created_at timestamptz NOT NULL DEFAULT transaction_timestamp(),PRIMARY KEY(tenant_id,id),UNIQUE(tenant_id,match_revision_id,receipt_version_id),UNIQUE(tenant_id,job_id,id),FOREIGN KEY(tenant_id,job_id,match_revision_id)REFERENCES app.supplier_match_revision(tenant_id,job_id,id),FOREIGN KEY(tenant_id,job_id,receipt_version_id)REFERENCES app.goods_receipt(tenant_id,job_id,id));
DO $$ DECLARE n text;BEGIN FOREACH n IN ARRAY ARRAY['supplier_match_proposal','supplier_match_revision','supplier_match_allocation'] LOOP EXECUTE format('ALTER TABLE app.%I OWNER TO jobguard_migration',n);EXECUTE format('ALTER TABLE app.%I ENABLE ROW LEVEL SECURITY',n);EXECUTE format('ALTER TABLE app.%I FORCE ROW LEVEL SECURITY',n);EXECUTE format('CREATE POLICY tenant_isolation ON app.%I FOR ALL TO jobguard_runtime,jobguard_migration USING(tenant_id=current_setting(''app.tenant_id'')::uuid) WITH CHECK(tenant_id=current_setting(''app.tenant_id'')::uuid)',n);EXECUTE format('GRANT SELECT,INSERT ON app.%I TO jobguard_runtime',n);EXECUTE format('REVOKE UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER ON app.%I FROM jobguard_runtime',n);END LOOP;END$$;
COMMIT;
